    elapsedMs: 0,
    started: false,
    matched: [],
    selection: { kind: 'closed' },
  });
  const resized = await exportedSnapshot(page);
  expect(String(resized.boardCode).split('-')[2]).not.toBe(
    String(beforeResize.boardCode).split('-')[2],
  );
});
